const input = $json;
return [{
  json: {
    userInput: String(input.chatInput ?? '').trim(),
    sessionId: String(input.sessionId ?? 'chat-session'),
    outputMode: 'chat',
    chatId: ''
  }
}];

if (!$json.userInput) {
  return [{
    json: {
      ...$json,
      userInput: 'help me use the citibike assistant'
    }
  }];
}
return [{json:$json}];

const env = $('input envelope').first().json;
const parsed = $json.output ?? {};
return [{
  json: {
    ...env,
    intent: String(parsed.intent ?? 'help'),
    stationQuery: String(parsed.stationQuery ?? ''),
    placeQuery: String(parsed.placeQuery ?? ''),
    currentLat: Number(parsed.currentLat ?? 0),
    currentLon: Number(parsed.currentLon ?? 0),
    usualStation: String(parsed.usualStation ?? ''),
    alias: String(parsed.alias ?? ''),
    rememberedStation: String(parsed.rememberedStation ?? ''),
    clarification: String(parsed.clarification ?? '')
  }
}];

const req = $('request fields').first().json;
const info = $('station information').first().json;
const status = $('station live status').first().json;
const query = String(req.stationQuery ?? '').trim();

function norm(s) {
  return String(s ?? '').toLowerCase()
    .replace(/&/g,' and ')
    .replace(/\bstreet\b/g,' st ')
    .replace(/\bavenue\b/g,' ave ')
    .replace(/\broad\b/g,' rd ')
    .replace(/\bboulevard\b/g,' blvd ')
    .replace(/[^a-z0-9]+/g,' ')
    .replace(/\s+/g,' ').trim();
}
function score(name, q, id) {
  if (String(q) === String(id)) return 100000;
  const a = norm(name), b = norm(q);
  if (!a || !b) return -999;
  if (a === b) return 10000;
  let s = 0;
  if (a.includes(b) || b.includes(a)) s += 2000;
  const A = new Set(a.split(' ')), B = new Set(b.split(' '));
  let overlap = 0;
  for (const t of B) if (A.has(t)) overlap++;
  s += (overlap / Math.max(B.size,1)) * 1200;
  s -= Math.abs(a.length-b.length);
  return s;
}
function meters(lat1,lon1,lat2,lon2) {
  const R=6371000, r=x=>x*Math.PI/180;
  const dLat=r(lat2-lat1), dLon=r(lon2-lon1);
  const a=Math.sin(dLat/2)**2+Math.cos(r(lat1))*Math.cos(r(lat2))*Math.sin(dLon/2)**2;
  return 2*R*Math.asin(Math.sqrt(a));
}

const infos = info?.data?.stations ?? [];
const statuses = status?.data?.stations ?? [];
const byId = new Map(statuses.map(s=>[String(s.station_id),s]));

const ranked = infos.map(s=>({s,score:score(s.name,query,s.station_id)})).sort((a,b)=>b.score-a.score);

if (!ranked.length || ranked[0].score < 250) {
  const matches = ranked.slice(0,5).map(x=>x.s.name);
  const text = `i couldnt confidently match "${query}" to a citibike station. closest matches: ${matches.join(', ')}.`;
  return [{json:{text,spokenText:`couldnt find a station called ${query}.`}}];
}

const i = ranked[0].s;
const live = byId.get(String(i.station_id)) ?? {};
const target = {
  stationId:String(i.station_id),
  name:String(i.name),
  lat:Number(i.lat),
  lon:Number(i.lon),
  openDocks:Number(live.num_docks_available ?? 0),
  bikesAvailable:Number(live.num_vehicles_available ?? live.num_bikes_available ?? 0),
  isReturning:live.is_returning === undefined ? true : Boolean(live.is_returning),
  isInstalled:live.is_installed === undefined ? true : Boolean(live.is_installed)
};
const canReturn = s => s && s.isInstalled && s.isReturning && s.openDocks >= 2;

const alternatives = infos.map(s=>{
  const l=byId.get(String(s.station_id)) ?? {};
  return {
    stationId:String(s.station_id),
    name:String(s.name),
    lat:Number(s.lat),
    lon:Number(s.lon),
    openDocks:Number(l.num_docks_available ?? 0),
    bikesAvailable:Number(l.num_vehicles_available ?? l.num_bikes_available ?? 0),
    isReturning:l.is_returning === undefined ? true : Boolean(l.is_returning),
    isInstalled:l.is_installed === undefined ? true : Boolean(l.is_installed),
    distanceMeters:Math.round(meters(target.lat,target.lon,Number(s.lat),Number(s.lon)))
  };
}).filter(s=>s.stationId!==target.stationId && s.distanceMeters<=1200 && canReturn(s))
  .sort((a,b)=>a.distanceMeters-b.distanceMeters || b.openDocks-a.openDocks);

let selected = target;
let text, spokenText;
const away = m => m < 75 ? 'right there' : `${Math.round(m/50)*50} meters away`;
const problem = s => !s.isInstalled || !s.isReturning ? 'is closed' : s.openDocks === 0 ? 'is full' : s.openDocks === 1 ? 'is almost full' : 'is too far';

if (canReturn(target)) {
  text = `${target.name} has ${target.openDocks} open docks right now, so youre good to return there. it also has ${target.bikesAvailable} bikes available.`;
  spokenText = `${target.name} has ${target.openDocks} docks open.`;
} else if (alternatives.length) {
  selected = alternatives[0];
  const url = `https://www.google.com/maps/dir/?api=1&destination=${selected.lat},${selected.lon}&travelmode=bicycling`;
  text = `${target.name} only has ${target.openDocks} open docks right now or isnt accepting returns. head to ${selected.name} instead — it has ${selected.openDocks} open docks and is about ${selected.distanceMeters} meters away.\n\ndirections: ${url}`;
  spokenText = `${target.name} ${problem(target)}. go to ${selected.name}, ${selected.openDocks} docks, ${away(selected.distanceMeters)}.`;
} else {
  text = `${target.name} only has ${target.openDocks} open docks right now or isnt accepting returns, and i couldnt find another station within about 1.2 kilometers with at least 2 open docks.`;
  spokenText = `${target.name} ${problem(target)}, and nothing nearby has space.`;
}

return [{json:{
  text,
  spokenText,
  selectedStation:selected,
  alternatives:alternatives.slice(0,4),
  lastUpdated:status?.last_updated ?? null
}}];

const req = $('request fields').first().json;
const geoRaw = $('geocode destination').first().json;
const info = $('nearby station information').first().json;
const status = $('nearby station status').first().json;

let geo = geoRaw;
if (Array.isArray(geoRaw)) geo = geoRaw[0];

// "find me a dock near me" from siri: no destination, so search around the riders gps instead
const hasGps = req.currentLat !== 0 && req.currentLon !== 0;
const nearMe = !String(req.placeQuery ?? '').trim() && hasGps;
const destLat = nearMe ? req.currentLat : Number(geo?.lat);
const destLon = nearMe ? req.currentLon : Number(geo?.lon);
const placeLabel = nearMe ? 'you' : req.placeQuery;

if (!Number.isFinite(destLat) || !Number.isFinite(destLon)) {
  const text = `i couldnt confidently find "${req.placeQuery}" on the map. try giving me a street address, intersection, or a more specific landmark.`;
  return [{json:{text,spokenText:`couldnt find ${req.placeQuery} on the map.`}}];
}

function meters(lat1,lon1,lat2,lon2) {
  const R=6371000, r=x=>x*Math.PI/180;
  const dLat=r(lat2-lat1), dLon=r(lon2-lon1);
  const a=Math.sin(dLat/2)**2+Math.cos(r(lat1))*Math.cos(r(lat2))*Math.sin(dLon/2)**2;
  return 2*R*Math.asin(Math.sqrt(a));
}
function norm(s) {
  return String(s ?? '').toLowerCase().replace(/&/g,' and ').replace(/[^a-z0-9]+/g,' ').replace(/\s+/g,' ').trim();
}
function matchScore(name,q) {
  const a=norm(name), b=norm(q);
  if(!a||!b) return -999;
  if(a===b) return 10000;
  let s=0;
  if(a.includes(b)||b.includes(a)) s+=1800;
  const A=new Set(a.split(' ')), B=new Set(b.split(' '));
  let overlap=0;
  for(const t of B) if(A.has(t)) overlap++;
  s+=(overlap/Math.max(B.size,1))*1000;
  return s-Math.abs(a.length-b.length);
}

const statuses = status?.data?.stations ?? [];
const byId = new Map(statuses.map(s=>[String(s.station_id),s]));

const stations = (info?.data?.stations ?? []).map(s=>{
  const l=byId.get(String(s.station_id)) ?? {};
  const lat=Number(s.lat), lon=Number(s.lon);
  return {
    stationId:String(s.station_id),
    name:String(s.name),
    lat,lon,
    openDocks:Number(l.num_docks_available ?? 0),
    bikesAvailable:Number(l.num_vehicles_available ?? l.num_bikes_available ?? 0),
    isReturning:l.is_returning === undefined ? true : Boolean(l.is_returning),
    isInstalled:l.is_installed === undefined ? true : Boolean(l.is_installed),
    distanceFromDestinationMeters:Math.round(meters(destLat,destLon,lat,lon))
  };
}).filter(s=>Number.isFinite(s.lat)&&Number.isFinite(s.lon));

const canReturn=s=>s&&s.isInstalled&&s.isReturning&&s.openDocks>=2;
const problem = s => !s.isInstalled || !s.isReturning ? 'is closed' : s.openDocks === 0 ? 'is full' : s.openDocks === 1 ? 'is almost full' : 'is too far';
const nearby=stations.filter(s=>s.distanceFromDestinationMeters<=1200)
  .sort((a,b)=>a.distanceFromDestinationMeters-b.distanceFromDestinationMeters || b.openDocks-a.openDocks);
const good=nearby.filter(canReturn);

let usual=null;
if(req.usualStation){
  const ranked=stations.map(s=>({s,score:matchScore(s.name,req.usualStation)})).sort((a,b)=>b.score-a.score);
  if(ranked.length&&ranked[0].score>=250) usual=ranked[0].s;
}

let selected=null;
let reason='nearest good dock';
if(usual && usual.distanceFromDestinationMeters<=1200 && canReturn(usual)){
  selected=usual;
  reason='usual dock is good';
}else if(good.length){
  selected=good[0];
  reason=usual ? 'usual dock needs a reroute' : 'best nearby dock';
}

let prefix='';
if(req.intent==='gps' && hasGps && !nearMe){
  const distance=Math.round(meters(req.currentLat,req.currentLon,destLat,destLon));
  prefix=`youre about ${distance} meters from ${req.placeQuery}. `;
}

if(!selected){
  const text=`${prefix}i couldnt find a station within about 1.2 kilometers of ${placeLabel} that currently has at least 2 open docks.`;
  return [{json:{text,spokenText:`no docks with space near ${placeLabel}.`,matchedPlace:nearMe ? 'current location' : (geo?.display_name ?? req.placeQuery)}}];
}

const url=`https://www.google.com/maps/dir/?api=1&destination=${selected.lat},${selected.lon}&travelmode=bicycling`;
const fromWhere = nearMe ? 'you' : 'the destination';

let text, spokenText;
const d = selected.distanceFromDestinationMeters;
const where = nearMe ? (d < 75 ? 'right there' : `${Math.round(d/50)*50} meters away`)
  : (d < 75 ? `right at ${req.placeQuery}` : `${Math.round(d/50)*50} meters from ${req.placeQuery}`);
if(reason==='usual dock is good'){
  text=`${prefix}your usual dock at ${selected.name} has ${selected.openDocks} open docks right now, so id keep using it.\n\ndirections: ${url}`;
  spokenText=`your usual dock has ${selected.openDocks} docks open.`;
}else if(reason==='usual dock needs a reroute'){
  text=`${prefix}your usual dock isnt the best return option right now. head to ${selected.name} instead — it has ${selected.openDocks} open docks and is about ${selected.distanceFromDestinationMeters} meters from ${placeLabel}.\n\ndirections: ${url}`;
  spokenText=`your usual dock ${problem(usual)}. go to ${selected.name}, ${selected.openDocks} docks, ${where}.`;
}else{
  text=`${prefix}${selected.name} looks like the best return option near ${placeLabel}. it has ${selected.openDocks} open docks and is about ${selected.distanceFromDestinationMeters} meters from ${fromWhere}.\n\ndirections: ${url}`;
  spokenText=`${selected.name} has ${selected.openDocks} docks open, ${where}.`;
}

return [{json:{
  text,
  spokenText,
  matchedPlace:nearMe ? 'current location' : (geo?.display_name ?? req.placeQuery),
  selectedStation:selected,
  alternatives:good.filter(s=>s.stationId!==selected.stationId).slice(0,4),
  lastUpdated:status?.last_updated ?? null
}}];

const data=$json;
const stations=data?.data?.stations ?? [];
let bikes=0,docks=0,full=0,oneDock=0,accepting=0,active=0;

for(const s of stations){
  const b=Number(s.num_vehicles_available ?? s.num_bikes_available ?? 0);
  const d=Number(s.num_docks_available ?? 0);
  const installed=s.is_installed===undefined ? true : Boolean(s.is_installed);
  const returning=s.is_returning===undefined ? true : Boolean(s.is_returning);
  bikes+=Number.isFinite(b)?b:0;
  docks+=Number.isFinite(d)?d:0;
  if(installed) active++;
  if(installed&&returning) accepting++;
  if(installed&&returning&&d===0) full++;
  if(installed&&returning&&d===1) oneDock++;
}
const text=`right now the live feed shows ${bikes.toLocaleString()} bikes available and ${docks.toLocaleString()} open docks across ${active.toLocaleString()} active stations. ${full.toLocaleString()} stations are full and ${oneDock.toLocaleString()} more only have 1 open dock.`;
const spokenText=`${bikes.toLocaleString()} bikes and ${docks.toLocaleString()} open docks citywide. ${full.toLocaleString()} stations are full.`;
return [{json:{text,spokenText,lastUpdated:data?.last_updated ?? null}}];

const req=$json;
let text;
if(req.alias && req.rememberedStation){
  text=`got it — ill treat ${req.rememberedStation} as your ${req.alias} dock in this conversation.`;
}else if(req.rememberedStation){
  text=`got it — ill remember ${req.rememberedStation} as one of your usual docks in this conversation.`;
}else{
  text=`got it. if you tell me the exact citibike station name and what you call it, like "my school dock is e 17 st & broadway", ill remember it for this chat.`;
}
const spokenText = req.rememberedStation
  ? (req.alias ? `got it, ${req.rememberedStation} is your ${req.alias} dock.` : `got it, ill remember ${req.rememberedStation}.`)
  : text;
return [{json:{text,spokenText}}];

const req=$json;
const text=req.clarification
  ? req.clarification
  : `you can ask me to check a specific citibike station, find a good return station near a place, remember what you call a usual dock, or use gps coordinates. for example: "find me a dock near nyu stern" or "gps 40.7295, -73.9965 going to union square".`;
const spokenText=req.clarification
  ? req.clarification
  : `you can ask if a station has room, or for a dock near a place or near you. for example, find me a dock near union square.`;
return [{json:{text,spokenText}}];

const env=$('input envelope').first().json;
const text=String($json.text ?? 'i couldnt build a response for that.');
const spokenText=String($json.spokenText ?? text);
return [{
  json:{
    ...$json,
    text,
    spokenText,
    outputMode:env.outputMode,
    chatId:env.chatId,
    sessionId:env.sessionId
  }
}];

// called by the ios shortcut arrival automation. returns one short sentence for speak text.
const body = $('arrival webhook').first().json.body ?? {};
const info = $('arrival station information').first().json;
const status = $('arrival station status').first().json;

const num = v => { const n = Number(v); return Number.isFinite(n) && n !== 0 ? n : null; };
const place = String(body.place ?? '').trim() || 'your destination';
const usualDock = String(body.usualDock ?? '').trim();
const destLat = num(body.destLat), destLon = num(body.destLon);
const curLat = num(body.lat), curLon = num(body.lon);
const useDest = destLat !== null && destLon !== null;
const centerLat = useDest ? destLat : curLat;
const centerLon = useDest ? destLon : curLon;
const fromWhere = useDest ? place : 'you';

if (centerLat === null || centerLon === null) {
  const text = 'no location from your phone.';
  return [{json:{text,spokenText:text}}];
}

function meters(lat1,lon1,lat2,lon2) {
  const R=6371000, r=x=>x*Math.PI/180;
  const dLat=r(lat2-lat1), dLon=r(lon2-lon1);
  const a=Math.sin(dLat/2)**2+Math.cos(r(lat1))*Math.cos(r(lat2))*Math.sin(dLon/2)**2;
  return 2*R*Math.asin(Math.sqrt(a));
}
function norm(s) {
  return String(s ?? '').toLowerCase()
    .replace(/&/g,' and ')
    .replace(/\bstreet\b/g,' st ')
    .replace(/\bavenue\b/g,' ave ')
    .replace(/[^a-z0-9]+/g,' ')
    .replace(/\s+/g,' ').trim();
}
function matchScore(name,q) {
  const a=norm(name), b=norm(q);
  if(!a||!b) return -999;
  if(a===b) return 10000;
  let s=0;
  if(a.includes(b)||b.includes(a)) s+=1800;
  const A=new Set(a.split(' ')), B=new Set(b.split(' '));
  let overlap=0;
  for(const t of B) if(A.has(t)) overlap++;
  s+=(overlap/Math.max(B.size,1))*1000;
  return s-Math.abs(a.length-b.length);
}
function howFar(m) {
  if (m < 75) return useDest ? `right at ${place}` : 'right there';
  return useDest ? `${Math.round(m/50)*50} meters from ${place}` : `${Math.round(m/50)*50} meters away`;
}
const docks = n => `${n} ${n===1?'dock':'docks'} open`;

const statuses = status?.data?.stations ?? [];
const byId = new Map(statuses.map(s=>[String(s.station_id),s]));
const stations = (info?.data?.stations ?? []).map(s=>{
  const l=byId.get(String(s.station_id)) ?? {};
  const lat=Number(s.lat), lon=Number(s.lon);
  return {
    stationId:String(s.station_id),
    name:String(s.name),
    lat,lon,
    openDocks:Number(l.num_docks_available ?? 0),
    isReturning:l.is_returning === undefined ? true : Boolean(l.is_returning),
    isInstalled:l.is_installed === undefined ? true : Boolean(l.is_installed),
    distanceMeters:Math.round(meters(centerLat,centerLon,lat,lon))
  };
}).filter(s=>Number.isFinite(s.lat)&&Number.isFinite(s.lon));

const canReturn = s => s && s.isInstalled && s.isReturning && s.openDocks >= 2;
const good = stations.filter(s=>s.distanceMeters<=1200 && canReturn(s))
  .sort((a,b)=>a.distanceMeters-b.distanceMeters || b.openDocks-a.openDocks);

let usual = null;
if (usualDock) {
  const ranked = stations.map(s=>({s,score:matchScore(s.name,usualDock)})).sort((a,b)=>b.score-a.score);
  if (ranked.length && ranked[0].score >= 250) usual = ranked[0].s;
}

let text, selected = null;
if (usual && canReturn(usual)) {
  selected = usual;
  text = `your usual dock has ${docks(usual.openDocks)}.`;
} else {
  let lead = '';
  if (usual) {
    const problem = !usual.isInstalled || !usual.isReturning ? 'is closed'
      : usual.openDocks === 0 ? 'is full' : 'is almost full';
    lead = `your usual dock ${problem}. `;
  }
  selected = good.find(s=>!usual || s.stationId!==usual.stationId) ?? null;
  text = selected
    ? (lead ? `${lead}go to ${selected.name}, ${selected.openDocks} docks, ${howFar(selected.distanceMeters)}.`
            : `${selected.name} has ${docks(selected.openDocks)}, ${howFar(selected.distanceMeters)}.`)
    : `${lead}no docks with space near ${fromWhere}.`;
}

return [{json:{
  text,
  spokenText:text,
  selectedStation:selected,
  usualMatched:usual ? usual.name : null,
  centeredOn:useDest ? 'destination' : 'current location',
  lastUpdated:status?.last_updated ?? null
}}];

// called by the "dock check" siri shortcut: {text, lat, lon, sessionId}
const body = $json.body ?? {};
const lat = Number(body.lat), lon = Number(body.lon);
const hasGps = Number.isFinite(lat) && Number.isFinite(lon) && lat !== 0 && lon !== 0;
const said = String(body.text ?? '').trim();
return [{
  json: {
    userInput: hasGps ? `${said} (my current gps coordinates are ${lat}, ${lon})` : said,
    sessionId: `siri-${String(body.sessionId ?? 'default').trim() || 'default'}`,
    outputMode: 'siri',
    chatId: ''
  }
}];

// siri reads "St" as "saint", "id" as "I.D." and spells out links, so tidy the sentence before it gets spoken.
// station names get shortened the way new yorkers say them: "W 15 St & 6 Ave" -> "West 15th and 6th"
function ordinal(n) {
  const v=n%100;
  return n + (v>=11&&v<=13 ? 'th' : ({1:'st',2:'nd',3:'rd'}[n%10] || 'th'));
}
const contractions = {
  i:'I', id:"I'd", ill:"I'll", im:"I'm", ive:"I've",
  youre:"you're", isnt:"isn't", couldnt:"couldn't", didnt:"didn't", cant:"can't", dont:"don't"
};
function forSpeech(s) {
  return String(s ?? '')
    .replace(/https?:\/\/\S+/g,'')
    .replace(/directions:\s*/gi,'')
    .replace(/&/g,' and ')
    .replace(/\bE\b(?=\s+\d)/g,'East')
    .replace(/\bW\b(?=\s+\d)/g,'West')
    .replace(/\b(\d+)\s+(St|Ave)\b/g,(m,n)=>ordinal(Number(n)))
    .replace(/\s+(St|Ave|Pl|Blvd|Rd|Dr)\b(?!\s+[A-Z0-9])/g,'')
    .replace(/\bAve\b/g,'Avenue')
    .replace(/\bPl\b/g,'Place')
    .replace(/\bBlvd\b/g,'Boulevard')
    .replace(/\b(i|id|ill|im|ive|youre|isnt|couldnt|didnt|cant|dont)\b/g,w=>contractions[w])
    .replace(/\s+/g,' ').trim();
}
return [{json:{spokenText:forSpeech($json.spokenText ?? $json.text)}}];
